from playwright.sync_api import sync_playwright
exec(open('fake_links.py').read())
src=open('wo_test.py').read(); lang='es'
exec(src[src.index('SEED3='):src.index('body=lambda')])
def shot(pg,name,wait=500): pg.wait_for_timeout(wait); pg.screenshot(path='/tmp/g/t_%s.png'%name)
with sync_playwright() as p:
    b=p.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox'])
    c=b.new_context(viewport={'width':400,'height':860},locale=lang,device_scale_factor=2); pg=c.new_page(); pg.errs=[]; pg.on('pageerror',lambda e:pg.errs.append(str(e)))
    pg.on('dialog',lambda d:d.accept()); pg.route('**/*',sb.handle); pg.add_init_script(SEED3); pg.goto('http://localhost:8765/index.html'); pg.wait_for_timeout(600)
    login(pg,'ana','secreta1',False)
    # en la rutina: técnicas planeadas y biserie (mismo circuito en los dos primeros)
    print('ejercicios', pg.evaluate("gymRoutines()[0].exercises.map(e=>e.id+':'+e.name+':'+e.circuit)"))
    pg.evaluate("(()=>{const a=gymRoutines();a[0].exercises[0].circuit=1;a[0].exercises[1].circuit=1;a[0].exercises[0].tech=['drop'];saveGymRoutines(a)})()")
    pg.click('nav button[data-tab="gym"]'); pg.wait_for_timeout(600)
    pg.evaluate("openGymEditor(gymRoutines()[0].id)"); pg.wait_for_timeout(600); pg.click('[data-ge-open]'); pg.wait_for_timeout(400)
    pg.click('[data-ge-tech="neg"]'); pg.evaluate("document.querySelector('.ge-tech').scrollIntoView({block:'center'})"); shot(pg,'editor'); pg.click('[data-ge-close]'); pg.wait_for_timeout(300); pg.click('#sheet-save'); pg.wait_for_timeout(500)
    print('tech rutina', pg.evaluate("gymRoutines()[0].exercises[0].tech"))
    pg.click('nav button[data-tab="hoy"]'); pg.wait_for_timeout(500); pg.click('[data-hd-start]'); pg.wait_for_timeout(700)
    pg.fill('.gym-set[data-ex="x1"][data-i="0"] .gym-in[data-f=kg]','62.5'); pg.fill('.gym-set[data-ex="x1"][data-i="0"] .gym-in[data-f=reps]','8'); pg.fill('.gym-set[data-ex="x1"][data-i="0"] .gym-in[data-f=rir]','2'); pg.click('.gym-set[data-ex="x1"][data-i="0"] .gym-check'); pg.wait_for_timeout(300)
    pg.evaluate("document.getElementById('gym-rest-x') && document.getElementById('gym-rest-x').click()")
    print('abierto', pg.evaluate("[...document.querySelectorAll('.gym-ex.open')].map(e=>e.dataset.exCard)"), pg.evaluate("[...document.querySelectorAll('[data-set-tags]')].map(e=>e.dataset.setTags).join(',')"))
    if not pg.locator('.gym-ex.open[data-ex-card="x1"]').count(): pg.click('[data-gym-toggle="x1"]'); pg.wait_for_timeout(400)
    pg.click('[data-set-tags="x1:1"]'); pg.wait_for_timeout(300); shot(pg,'picker')
    pg.click('.set-tags-pick [data-tech="neg"]'); pg.wait_for_timeout(200); pg.click('.set-tags-pick [data-tech="rp"]'); pg.wait_for_timeout(200); pg.click('[data-set-tags="x1:1"]'); pg.wait_for_timeout(300)
    pg.fill('.gym-set[data-ex="x1"][data-i="1"] .gym-in[data-f=rir]','0'); pg.wait_for_timeout(200)
    print('series', pg.evaluate("JSON.stringify(gymLogs()[keyDate()].ex.x1.slice(0,2))"))
    pg.evaluate("document.querySelector('.gym-circ') && document.querySelector('.gym-circ').scrollIntoView({block:'start'})"); shot(pg,'sesion')
    print('grupo', pg.inner_text('.gym-circ'))
    print('errs',pg.errs)
